#include <stdio.h>
#include <stdlib.h>

int *parent, *dsu_rank;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (dsu_rank[a] < dsu_rank[b]) {
        int t = a; a = b; b = t;
    }
    parent[b] = a;
    if (dsu_rank[a] == dsu_rank[b]) dsu_rank[a]++;
}

