    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    parent = (int*)malloc((N + 1) * sizeof(int));
    dsu_rank = (int*)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) parent[i] = i;

