    for (int i = 1; i <= N; i++) head[i] = -1;

    int *to = (int*)malloc((2 * M) * sizeof(int));
    int *nxt = (int*)malloc((2 * M) * sizeof(int));
    int *deg = (int*)calloc(N + 1, sizeof(int));
    int *edgeU = (int*)malloc(M * sizeof(int));
    int *edgeV = (int*)malloc(M * sizeof(int));

    int idx = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        edgeU[i] = u;
        edgeV[i] = v;

        to[idx] = v;
        nxt[idx] = head[u];
        head[u] = idx++;

        to[idx] = u;
        nxt[idx] = head[v];
        head[v] = idx++;

        deg[u]++;
        deg[v]++;

        unite(u, v);
    }

    int *compSize = (int*)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) {
        compSize[find(i)]++;
    }

    long long *edgeCnt = (long long*)calloc(N + 1, sizeof(long long));
    for (int i = 0; i < M; i++) {
        edgeCnt[find(edgeU[i])]++;
    }

    int *compHead = (int*)malloc((N + 1) * sizeof(int));
    int *compNext = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) compHead[i] = -1;

    for (int i = 1; i <= N; i++) {
        int r = find(i);
        compNext[i] = compHead[r];
        compHead[r] = i;
    }

    int *mark = (int*)calloc(N + 1, sizeof(int));

    for (int r = 1; r <= N; r++) {
        if (compSize[r] == 0) continue;

        long long complete = (long long)compSize[r] * (compSize[r] - 1) / 2;
        if (edgeCnt[r] < complete) {
            int v = -1;

            for (int x = compHead[r]; x != -1; x = compNext[x]) {
                if (deg[x] < compSize[r] - 1) {
                    v = x;
                    break;
                }
            }

            if (v == -1) continue;

            int token = r;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                mark[to[e]] = token;
            }

            for (int x = compHead[r]; x != -1; x = compNext[x]) {
                if (x != v && mark[x] != token) {
                    printf("%d %d\n", v, x);
                    return 0;
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}
